    to: String,
    overwrite: bool,
) -> PyObjectStoreResult<()> {
    let runtime = get_runtime();
    let from_ = from_.into();
    let to = to.into();
    py.detach(|| {
        let fut: Pin<Box<dyn Future<Output = _> + Send>> = if overwrite {
            Box::pin(store.as_ref().copy(&from_, &to))
        } else {
